const f = $('Job preferences').first().json;
const cfg = $('Configuration').first().json;
const keywords = String(f['Target role or keywords'] || '').split(',').map(s => s.trim()).filter(Boolean).slice(0, 3);
const location = (String(f['Preferred locations'] || '').split(',')[0] || '').trim() || 'Remote';
const senMap = { 'fresher / entry': 'entry-level', 'fresher': 'entry-level', 'entry': 'entry-level', 'associate': 'associate', 'mid': 'mid-senior', 'senior': 'mid-senior' };
const exp = senMap[String(f['Seniority'] || '').toLowerCase()];
const input = { keyword: keywords.length ? keywords : ['AI Engineer'], location: location, publishedAt: cfg.published_within || 'r604800', saveOnlyUniqueItems: true, enrichCompanyData: false, maxItems: Number(cfg.max_jobs) || 150 };
if (exp) input.experienceLevel = [exp];
return [{ json: input }];

const f = $('Job preferences').first().json;
const seniority = String(f['Seniority'] || '').toLowerCase();
const isJunior = /fresher|entry|associate/.test(seniority);
const wantLocs = String(f['Preferred locations'] || '').toLowerCase().split(/[,;/]| or /).map(s => s.trim()).filter(Boolean);
const seniorTitle = /(senior|sr\.?|lead|principal|staff|architect|manager|director|head|vp|avp|\biii\b|sde-?3|sde-?ii)/i;
const seen = new Set();
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  const title = String(r.jobTitle || '');
  const loc = String(r.location || '').toLowerCase();
  const key = (String(r.applyUrl || r.jobUrl || '') || (String(r.companyName || '') + '|' + title)).toLowerCase().trim();
  if (!key || seen.has(key)) continue;
  seen.add(key);
  if (isJunior && seniorTitle.test(title)) continue;
  if (/executive/i.test(String(r.experienceLevel || ''))) continue;
  let maxY = -1;
  for (let i = 0; i < 5; i++) {
    const m = String(r['yearsOfExperience/' + i + '/years'] || '').match(/(\d+)/);
    if (m) maxY = Math.max(maxY, parseInt(m[1]));
  }
  const desc = String(r.jobDescription || '');
  const re = /(\d+)\s*(?:\+|-\s*\d+)?\s*(?:years|yrs)/gi;
  let tm;
  while ((tm = re.exec(desc)) !== null) {
    const n = parseInt(tm[1]);
    if (n <= 20) maxY = Math.max(maxY, n);
  }
  if (isJunior && maxY >= 4) continue;
  if (maxY >= 8) continue;
  if (wantLocs.length) {
    const ok = wantLocs.some(w => w && loc.includes(w)) || /remote|anywhere/.test(loc);
    if (!ok) continue;
  }
  out.push({ json: r });
}
return out;

const f = $('Job preferences').first().json;
const j = $json;
const jd = String(j.jobDescription || '').slice(0, 4500);
$json.matchPrompt = 'You are a strict job screener for a job seeker. They want -> role/keywords: ' + (f['Target role or keywords'] || '') + '. seniority: ' + (f['Seniority'] || '') + '. preferred locations: ' + (f['Preferred locations'] || '') + '. their top skills: ' + (f['Your top skills'] || '') + '. deal-breakers (reject if the job requires any of these): ' + (f['Deal-breakers (skip jobs needing these)'] || '') + '. Infer the candidate experience from their seniority (Fresher/Entry = 0 to 1 years). Judge THIS job on relevance and eligibility. Return ONLY JSON: {"relevant": true or false, "fit": 0 to 100, "verdict": "APPLY or STRETCH or REJECT", "reason": "one short sentence"}. Rules: REJECT if the job needs clearly more years than the candidate has, is senior/lead/principal/manager level, requires a deal-breaker, or is a different field. APPLY if a genuine fit. STRETCH if close. JOB TITLE: ' + (j.jobTitle || '') + '. COMPANY: ' + (j.companyName || '') + '. LOCATION: ' + (j.location || '') + '. LEVEL: ' + (j.experienceLevel || '') + '. DESCRIPTION: ' + jd;
return $json;

const prompts = $('Build screening prompt').all();
const inputs = $input.all();
const cfg = $('Configuration').first().json;
const threshold = Number(cfg.fit_threshold) || 40;
const topN = Number(cfg.top_matches) || 5;
const scored = [];
for (let i = 0; i < inputs.length; i++) {
  let m = { relevant: false, fit: 0, verdict: 'REJECT', reason: '' };
  try {
    let t = inputs[i].json.output;
    if (typeof t !== 'string') t = JSON.stringify(t || {});
    t = t.replace(/```json|```/g, '').trim();
    m = JSON.parse(t);
  } catch (e) {}
  const lead = (prompts[i] && prompts[i].json) || inputs[i].json;
  scored.push({ json: { ...lead, _fit: Number(m.fit) || 0, verdict: String(m.verdict || 'REJECT').toUpperCase(), reason: m.reason || '', _relevant: !!m.relevant } });
}
let keep = scored.filter(r => r.json.verdict !== 'REJECT' && r.json._fit >= threshold);
if (keep.length === 0) keep = scored.filter(r => r.json._fit >= Math.max(20, threshold - 10));
keep.sort((a, b) => b.json._fit - a.json._fit);
return keep.slice(0, topN);

const f = $('Job preferences').first().json;
const profile = f['Your resume or profile'] || '';
const rules = 'Rules: Do not use em-dashes, use commas colons or periods instead. Use ONLY facts present in the candidate profile text below, never invent skills, employers, dates, metrics or numbers. If the candidate lacks something the job wants, do not claim it, frame it honestly. Write in plain, human language.';
const j = $json;
const jd = String(j.jobDescription||'').slice(0,6000);
const role = j.jobTitle||'';
const company = (j.companyName||'').replace(/"/g,'');
const PROFILE = 'CANDIDATE PROFILE (the only source of truth, do not invent beyond this): ' + profile;
$json.resumePrompt = 'Write a tailored resume as JSON for this candidate and job. ' + rules + ' Output ONLY JSON with this shape: {"_company":"' + company + '","basics":{"name":"","title":"","email":"","phone":"","location":"","links":[{"label":"","url":""}]},"summary":"","experience":[],"projects":[{"name":"","url":"","tech":[],"bullets":[]}],"skills":[],"education":[{"degree":"","school":"","dates":""}]}. Extract the name, email, phone and links from the profile text. Keep it to 3 sections (summary, projects, skills). ' + PROFILE + ' ROLE: ' + role + ' at ' + company + '. JD: ' + jd;
$json.coverPrompt = 'Write a humanized cover letter as JSON. ' + rules + ' 5 to 7 short paragraphs, open with the job and company, include one honest line if the candidate lacks the required years, and include one concrete achievement from the profile if one exists. Output ONLY JSON: {"name":"","contact":"","links":[{"label":"","url":""}],"paragraphs":[],"filename":""}. Use the candidate name and contact from the profile. ' + PROFILE + ' ROLE: ' + role + ' at ' + company + '. JD: ' + jd;
return $json;

