var header='<header><h1>'+esc(b.name)+'</h1><div class="title">'+esc(b.title)+'</div><div class="contact">'+esc(b.email)+'<span class="dot">.</span>'+esc(b.phone)+'<span class="dot">.</span>'+esc(b.location)+contactExtra+'</div></header>';
